document.addEventListener('DOMContentLoaded', () => {
  const isHubeditoArticlePage = document.querySelector(
    '.hubedito-article-page-template',
  );

  if (isHubeditoArticlePage) {
    const element = document.querySelector('.ace-shorttitle');

